#if UNITY_EDITOR
using System;using System.Linq;using NUnit.Framework;using SporeGobbo.Geometry;
public sealed class Stage62CTests
{
 [Test]public void AuthoredIntroIsDeterministicCompleteAndHasNoStressFallback(){var a=new IntroLayout();var b=new IntroLayout();Assert.AreEqual(a.Fingerprint(),b.Fingerprint());var w=new StreamingWorld(160,80,IntroLayout.Seed,a);for(int y=0;y<80;y++)for(int x=0;x<160;x++){Assert.IsTrue(a.TrySolid(x,y,out bool s));Assert.AreEqual(s||a.Protected(x,y),w.IsSolid(x,y));}}
 [Test]public void NewbornCanReachObstructionButCannotBypassIt(){var d=new IntroLayout();var state=new RegionTerrainState("intro",160,80,d);Assert.Greater(state.Route(d.Birth,d.DigApproach,3).Count,0);Assert.AreEqual(0,state.Route(d.Birth,d.Exit,3).Count);var edit=state.TakeMutationControl();Assert.Greater(edit(d.Plug,0,c=>true),0);Assert.Greater(state.Route(d.Birth,d.Exit,3).Count,0);}
 [Test]public void EveryAuthoredBeatHasForwardClearanceAfterExcavation(){var d=new IntroLayout();var state=new RegionTerrainState("intro",160,80,d);state.TakeMutationControl()(d.Plug,0,c=>true);foreach(var p in d.Route){Assert.IsTrue(state.Fits(p,3),p.ToString());Assert.Greater(state.Route(p,d.Exit,3).Count,0,p.ToString());}}
 [Test]public void ConcealedPocketsArePreexistingFloorAndSealed(){var d=new IntroLayout();var w=new StreamingWorld(160,80,0,d);foreach(var g in d.Concealed){Assert.Greater(g.Cells.Length,0);Assert.IsTrue(g.Cells.All(i=>!w.IsSolid(i%160,i/160)));}using(var discover=new CaveDiscovery(w,new DiscoveryIndex(w,d.Concealed))){discover.SeedKnown(d.Known);foreach(var g in d.Concealed)Assert.IsFalse(g.Cells.Any(i=>discover.Shown(i%160,i/160)));}}
 [Test]public void PlacementRequiresOwnerDomainInstanceRevisionAndSafety(){var d=new IntroLayout();var s=new RegionTerrainState("intro",160,80,d);Assert.Throws<InvalidOperationException>(()=>s.TakePlacementControl());s.TakeMutationControl();var place=s.TakePlacementControl();var cells=d.CollapseMasks[0];Assert.IsFalse(place(new TerrainPlacementRequest(Guid.NewGuid(),0,"a",cells),c=>true).Accepted);Assert.IsFalse(place(new TerrainPlacementRequest(s.InstanceId,1,"a",cells),c=>true).Accepted);Assert.IsFalse(place(new TerrainPlacementRequest(s.InstanceId,0,"a",cells),c=>false).Accepted);Assert.IsFalse(place(new TerrainPlacementRequest(s.InstanceId,0,"a",new[]{new DualTile(99,40)}),c=>true).Accepted);Assert.AreEqual(0,s.Revision);}
 [Test]public void PlacementIsOneRevisionAtomicIdempotentAndPhysicallySolid(){var d=new IntroLayout();var s=new RegionTerrainState("intro",160,80,d);s.TakeMutationControl();var place=s.TakePlacementControl();int publications=0;s.Committed+=(c,r)=>publications++;var cells=d.CollapseMasks[0];var result=place(new TerrainPlacementRequest(s.InstanceId,0,"collapse.0",cells),c=>true);Assert.IsTrue(result.Accepted);Assert.AreEqual(1,s.Revision);Assert.AreEqual(1,publications);Assert.IsTrue(cells.All(c=>s.World.IsSolid(c.X,c.Y)));Assert.IsFalse(place(new TerrainPlacementRequest(s.InstanceId,1,"collapse.0",cells),c=>true).Accepted);Assert.Throws<InvalidOperationException>(()=>s.ExportDeltas());Assert.Throws<InvalidOperationException>(()=>s.World.Refill(10,10));}
 [Test]public void MalformedPlacementRejectsAllCellsBeforeMutation(){var d=new IntroLayout();var s=new RegionTerrainState("intro",160,80,d);s.TakeMutationControl();var place=s.TakePlacementControl();var cells=d.CollapseMasks[0].Concat(new[]{new DualTile(-1,0)}).ToArray();Assert.IsFalse(place(new TerrainPlacementRequest(s.InstanceId,0,"bad",cells),c=>true).Accepted);Assert.AreEqual(0,s.Revision);Assert.IsTrue(d.CollapseMasks[0].All(c=>!s.World.IsSolid(c.X,c.Y)));}
 [Test]public void TrailingMasksPreserveForwardEscapeAndRejectOccupancy(){var d=new IntroLayout();var w=new StreamingWorld(160,80,0,d);for(int i=0;i<d.CollapseMasks.Count;i++){Assert.IsFalse(IntroPlacementSafety.HasForwardRoute(w,d,d.CollapseCenters[i],d.CollapseMasks[i]));var ahead=new Point2(d.Thresholds[i],i==0?51:i==1?35:i==2?49:i==3?47:43);Assert.IsTrue(IntroPlacementSafety.HasForwardRoute(w,d,ahead,d.CollapseMasks[i]),"zone "+i);}}
 [Test]public void MissingPlacementCapabilityCannotBeUsedAsGeneralSetSolid(){var s=new RegionTerrainState("no-domain",144,128,new ExpeditionLayout());s.TakeMutationControl();var place=s.TakePlacementControl();Assert.IsFalse(place(new TerrainPlacementRequest(s.InstanceId,0,"bad",new[]{new DualTile(20,100)}),c=>true).Accepted);}
}
#endif
